mapper.select:
SELECT caap.pack_number as pack_id_n, cap.*, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'ABS_TYPE' and s.code_value = cap.business_type) business_type_n, su.description AS create_person, ( SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = cap.company_id ) AS company_name, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = cap.unit_id ) AS unit_name, caap.base_date, caap.pack_number, pack.asset_contract_count, rent.asset_rent_count, pack.uncollected_due_amount, pack.uncollected_principal, pack.uncollected_interest, pack.collected_due_amount, pack.collected_principal, pack.collected_interest, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CHS.CURRENCY_TYPE' and scv.value = cap.currency_code) as currency_code_n, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'ABS.PROJECT_STATUS' and scv.value = cap.project_status) as project_status_n, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'ABS.BASE_ASSET_TYPE' and scv.value = cap.base_asset_type) as base_asset_type_n
FROM ct_abs_project cap left join ct_abs_assets_package caap on cap.pack_id = caap.pack_id left join pack on pack.pack_id = caap.pack_id left join rent on rent.pack_id = caap.pack_id left join sys_user su on su.user_id = cap.user_id 1=1 and cap.company_id = #{request.companyId}
and cap.project_name like concat('%',concat(#{projectName},'%'))
and cap.project_number like concat('%',concat(#{projectNumber},'%'))
and cap.project_id = #{projectId}
and cap.project_status = #{projectStatus}
and cap.project_date >= #{projectDateStart}
and cap.project_date <= #{projectDateEnd}
and cap.issue_amount = #{issueAmount}
and cap.issue_amount >= #{amountFrom}
and cap.issue_amount <= #{amountTo}
and (cap.project_number like concat('%',concat(#{nameOrNumber},'%')) or cap.project_name like concat('%',concat(#{nameOrNumber},'%')))
and su.description like concat('%',concat(#{createPerson},'%'))
order by cap.creation_date desc
